app.post('/api/reconciliation/:shiftId/decide',auth,roles('MANAGER'),async(req,res)=>{try{const out=await tx(async c=>{let q=await c.query('SELECT * FROM reconciliation WHERE shift_id=$1 AND station_id=$2 FOR UPDATE',[req.params.shiftId,req.user.stationId]);if(!q.rowCount){const sh=await c.query('SELECT * FROM shifts WHERE id=$1 AND station_id=$2',[req.params.shiftId,req.user.stationId]);if(!sh.rowCount)throw Error('Shift not found');const expected=n(sh.rows[0].opening_cash)+(await c.query("SELECT COALESCE(SUM(CASE WHEN direction='IN' THEN amount ELSE -amount END),0) x FROM cash_movements WHERE shift_id=$1",[req.params.shiftId])).rows[0].x;q=await c.query(`INSERT INTO reconciliation(station_id,shift_id,expected_cash) VALUES($1,$2,$3) RETURNING *`,[req.user.stationId,req.params.shiftId,expected]);}
 const before=q.rows[0],decision=req.body.decision,actual=req.body.actualCash==null?before.actual_cash:n(req.body.actualCash);if(!['RESOLVE','PENDING','ESCALATE'].includes(decision))throw Error('Invalid decision');const variance=actual==null?null:Number(actual)-n(before.expected_cash);if(decision==='RESOLVE'&&(variance==null||Math.abs(variance)>=0.01))throw Error('Cannot resolve with cash variance');const status=decision==='RESOLVE'?'RECONCILED':decision==='ESCALATE'?'ESCALATED':'PENDING';const updated=(await c.query(`UPDATE reconciliation SET actual_cash=$1,cash_variance=$2,status=$3,reason=$4,decided_by=$5,decided_at=now() WHERE id=$6 RETURNING *`,[actual,variance,status,req.body.reason||null,req.user.sub,before.id])).rows[0];await audit(c,req.user,'RECONCILIATION',before.id,'DECIDE',before,updated,req.body.reason||decision);return updated;});res.json(out);}catch(e){res.status(400).json({error:e.message});}});



